package com.ppms.admin.service;
import com.ppms.admin.api.workforce.WorkforceDtos.*;import com.ppms.admin.domain.workforce.Absence;import com.ppms.admin.repositories.workforce.*;import com.ppms.shared.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor public class AbsenceService {private final AbsenceRepository repository;private final EmployeeRepository employees;@Transactional(readOnly=true)public List<AbsenceDto> list(UUID employeeId){requireEmployee(employeeId);return repository.findByEmployeeId(employeeId).stream().map(this::dto).toList();}@Transactional public AbsenceDto create(UUID employeeId,AbsenceRequest r){requireEmployee(employeeId);return dto(repository.save(apply(new Absence(),employeeId,r)));}@Transactional public AbsenceDto update(UUID employeeId,UUID id,AbsenceRequest r){return dto(apply(find(employeeId,id),employeeId,r));}@Transactional public void delete(UUID employeeId,UUID id){repository.delete(find(employeeId,id));}private Absence find(UUID employeeId,UUID id){Absence a=repository.findById(id).orElseThrow(()->new EntityNotFoundException("Absence",id));if(!a.getEmployeeId().equals(employeeId))throw new EntityNotFoundException("Absence",id);return a;}private void requireEmployee(UUID id){if(!employees.existsById(id))throw new EntityNotFoundException("Employee",id);}private Absence apply(Absence a,UUID employeeId,AbsenceRequest r){if(r.toDate().isBefore(r.fromDate()))throw new ValidationException("Absence toDate cannot precede fromDate");a.setEmployeeId(employeeId);a.setFromDate(r.fromDate());a.setToDate(r.toDate());a.setType(r.type());a.setApprovedBy(r.approvedBy());return a;}private AbsenceDto dto(Absence a){return new AbsenceDto(a.getId(),a.getEmployeeId(),a.getFromDate(),a.getToDate(),a.getType(),a.getApprovedBy());}}
